        return np.nan
    mom = prices[-1] / prices[-window-1] - 1
    mean_rev = (prices[-window-1] / prices[-window-2]) - 1
    vol = np.std(prices[-window:] / prices[-window-1:-1] - 1)
    return 0.7 * mom - 0.15 * mean_rev + 0.15 * (1 / (vol + 1e-8))

def mean_return_7_v1(prices, window=7):
    if len(prices) < window + 1 or np.any(np.isnan(prices[-window-1:])):
        return np.nan
    r = prices[-window:] / prices[-window-1:-1] - 1
    return np.mean(r)

def momentum_3_comb_log_return_3_v2(prices, window=3):
    if len(prices) < window + 2 or np.any(np.isnan(prices[-window-2:])):
        return np.nan
    momentum = prices[-1] / prices[-window-1] - 1
    log_rets = np.log(prices[-window:] / prices[-window-1:-1])
    log_sum = np.sum(log_rets)
    volatility = np.std(log_rets)
    return 0.4 * momentum + 0.4 * log_sum + 0.2 * (1 / (volatility + 1e-8))

def momentum_3_v3(prices, window=3):
    if len(prices) < window + 2 or np.any(np.isnan(prices[-window-2:])):
        return np.nan
    mom = (prices[-1] - prices[-window-1]) / (np.abs(prices[-window-1]) + 1e-8)
    mean_rev = (prices[-window-1] - prices[-window-2]) / (np.abs(prices[-window-2]) + 1e-8)
    return 0.85 * mom - 0.15 * mean_rev

def mean_return_3_comb_momentum_3_v3(prices, window=3):
    if len(prices) < window + 2 or np.any(np.isnan(prices[-window-2:])):
        return np.nan
    r = prices[-window:] / prices[-window-1:-1] - 1
    mean_r = np.mean(r)
    momentum = prices[-1] / prices[-window-1] - 1
    volatility = np.std(r) + 1e-8
    min_r = np.min(r)
    return 0.45 * (mean_r / volatility) + 0.25 * mean_r + 0.2 * momentum + 0.1 * (mean_r - min_r)

def momentum_21_comb_ma_21_comb_std_return_21_v1(prices, window=21):
    if len(prices) < window + 1 or np.any(np.isnan(prices[-window-1:])):
        return np.nan
    momentum = prices[-1] / prices[-window-1] - 1
    ma_21 = np.mean(prices[-window:])
    r = prices[-window:] / prices[-window-1:-1] - 1
    r = r[~np.isnan(r)]
    if len(r) == 0:
        return np.nan
    std_r = np.std(r)
    mean_r = np.mean(r)
    sharpe = mean_r / (std_r + 1e-8)
    return (momentum * 0.45 + ma_21 * 0.35 + std_r * 0.2) * (1 + 0.41 * mean_r + 0.14 * sharpe)

def mean_return_7_comb_ma_3_v1(prices, window=7):
    if len(prices) < window + 3 or np.any(np.isnan(prices[-window-3:])):
        return np.nan
    r = prices[-window:] / prices[-window-1:-1] - 1
    vol = np.std(r) + 1e-8
    skew = np.mean(((r - np.mean(r)) / vol)**3)
    ma_3 = np.mean(prices[-3:])
    return ((np.mean(r) / vol) + 0.1 * skew) * (1 + 0.12 * ma_3)

def mean_return_7_comb_ma_7_comb_log_return_7_v1(prices, window=7):
    if len(prices) < window + 3 or np.any(np.isnan(prices[-window-3:])):
        return np.nan
    r = prices[-window:] / prices[-window-1:-1] - 1
    if len(r) == 0:
        return np.nan
    mean_r = np.mean(r)
    vol = np.std(r) + 1e-8
    skew = np.mean(((r - mean_r) / vol)**3)
    ma_7 = np.mean(prices[-7:])
    log_ret = np.log(prices[-1] / prices[-window]) / window
    return (mean_r / vol + 0.08 * skew) * (0.6 * ma_7 + 0.4 * log_ret)

def mean_return_7_comb_ma_7_comb_log_return_7_v2(prices, window=7):
    if len(prices) < window + 5 or np.any(np.isnan(prices[-window-5:])):
        return np.nan
    r = prices[-window:] / prices[-window-1:-1] - 1
    if len(r) == 0:
        return np.nan
    mean_r = np.mean(r)
    vol = np.std(r) + 1e-8
    skew = np.mean(((r - mean_r) / vol)**3)
    ma_7 = np.mean(prices[-7:])
    log_ret = np.log(prices[-1] / prices[-window]) / window
    rel_pos = (prices[-1] - np.min(prices[-window:])) / (np.max(prices[-window:]) - np.min(prices[-window:]) + 1e-8)
    return (mean_r / vol + 0.08 * skew + 0.12 * rel_pos) * (0.5 * ma_7 + 0.5 * log_ret)

def rsi_momentum_comb_14_v2(prices, window=14):
    if len(prices) < window + 2 or np.any(np.isnan(prices[-window-1:])):
        return np.nan
    r = np.diff(prices[-window-1:])
    gain = np.mean(np.maximum(r, 0))
    loss = np.mean(np.maximum(-r, 0))
    rsi = 100 - 100 / (1 + gain / (loss + 1e-8))
    momentum = prices[-1] / (prices[-window-1] + 1e-8) - 1
    volatility = np.std(r) + 1e-8
    return 0.6 * (rsi / 100) + 0.25 * momentum + 0.15 * (momentum / volatility)

