    return std_r * (1 + 0.25 * sharpe)

def volatility_3_v2(prices, window=3):
    if len(prices) < window + 1 or np.any(np.isnan(prices[-window-1:])):
        return np.nan
    logret = np.log(prices[-window:] / prices[-window-1:-1])
    mean_logret = np.mean(logret)
    std_logret = np.std(logret)
    upside = np.mean(logret[logret > 0]) if np.any(logret > 0) else 0
    return std_logret * (1 + 0.3 * mean_logret + 0.15 * upside)

def std_return_3_comb_volatility_3_v1(prices, window=3):
