    std_r = np.std(r)
    logret = np.log(prices[-window:] / prices[-window-1:-1])
    std_logret = np.std(logret)
    return (std_r + std_logret) * (1 + 0.2 * mean_r + 0.2 * np.mean(logret))

def price_position_7_v2(prices, window=7):
    if len(prices) < window or np.any(np.isnan(prices[-window:])):
        return np.nan
    p = prices[-window:]
    rel_pos = (p[-1] - np.min(p)) / (np.max(p) - np.min(p) + 1e-8)
    momentum = (p[-1] / (p[0] + 1e-8)) - 1
    return rel_pos * (1 + 0.7 * momentum)

